/* Accessibility Styles */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background-color: #333;
  color: #fff;
  padding: 0.5em;
  z-index: 1;
}

.skip-link:focus {
  top: 0;
}

